import re
from pathlib import Path

path = Path(r'src/app/[locale]/free/uploadpage/upload-side-bar.tsx')
text = path.read_text(encoding='utf-8')
text = text.replace('\r\n', '\n')

pattern = r"const \{ video_type, setVideoType, theme, setTheme, topic, setTopic, titles, setTitles, niche, setNiche \} =\s*useVideoSettingViewModel\(\);"
replacement = """const {\n    video_type,\n    setVideoType,\n    theme,\n    setTheme,\n    topic,\n    setTopic,\n    titles,\n    setTitles,\n    niche,\n    setNiche,\n    selectedTitle,\n    setSelectedTitle,\n    title: currentTitle,\n    setTitle,\n  } = useVideoSettingViewModel();"""
text, count = re.subn(pattern, replacement, text)
if count != 1:
    raise SystemExit('Failed to replace view model destructuring')

pattern = r"const \[collapsed, setCollapsed\] = useState\(false\);"
replacement = """const [collapsed, setCollapsed] = useState(false);\n  const [activeTitleIndex, setActiveTitleIndex] = useState<number | null>(null);"""
text, count = re.subn(pattern, replacement, text, count=1)
if count != 1:
    raise SystemExit('Failed to insert activeTitleIndex state')

block_pattern = re.compile(
    r"  const handleTitleChange = \(index: number, value: string\) => {\n\s*const updated = \[\.\.\.titles];\n\s*updated\[index] = value;\n\s*setTitles\(updated\);\n\s*};\n\s*\n\s*const addTitle = \(\) => {\n\s*if \(titles.length < 5\) setTitles\(\[\.\.\.titles, \"\"\]\);\n\s*};\n\s*\n\s*const removeTitle = \(index: number\) => {\n\s*const updated = \[\.\.\.titles];\n\s*updated.splice\(index, 1\);\n\s*setTitles\(updated\);\n\s*};",
    re.DOTALL,
)
new_block = """  useEffect(() => {\n    if (titles.length === 0) {\n      if (activeTitleIndex !== null) {\n        setActiveTitleIndex(null);\n      }\n      if (selectedTitle !== \"\") {\n        setSelectedTitle(\"\");\n      }\n      if (currentTitle !== \"\") {\n        setTitle(\"\");\n      }\n      return;\n    }\n\n    const nextIndex =\n      activeTitleIndex === null ? 0 : Math.min(activeTitleIndex, titles.length - 1);\n    const nextTitle = titles[nextIndex];\n\n    if (activeTitleIndex !== nextIndex) {\n      setActiveTitleIndex(nextIndex);\n    }\n\n    if (selectedTitle !== nextTitle) {\n      setSelectedTitle(nextTitle);\n    }\n\n    if (currentTitle !== nextTitle) {\n      setTitle(nextTitle);\n    }\n  }, [titles, activeTitleIndex, selectedTitle, currentTitle, setSelectedTitle, setTitle]);\n\n  const handleSelectTitle = (index: number, value: string) => {\n    setActiveTitleIndex(index);\n    setSelectedTitle(value);\n    setTitle(value);\n  };\n\n  const handleTitleChange = (index: number, value: string) => {\n    const updated = [...titles];\n    updated[index] = value;\n    setTitles(updated);\n\n    if (activeTitleIndex === index || (activeTitleIndex === null && index === 0)) {\n      handleSelectTitle(index, value);\n    }\n  };\n\n  const addTitle = () => {\n    if (titles.length >= 5) {\n      return;\n    }\n    const nextTitles = [...titles, \"\"];\n    setTitles(nextTitles);\n    handleSelectTitle(nextTitles.length - 1, \"\");\n  };\n\n  const removeTitle = (index: number) => {\n    const updated = [...titles];\n    updated.splice(index, 1);\n    setTitles(updated);\n\n    if (updated.length === 0) {\n      setActiveTitleIndex(null);\n      setSelectedTitle(\"\");\n      setTitle(\"\");\n      return;\n    }\n\n    if (activeTitleIndex === null) {\n      handleSelectTitle(0, updated[0]);\n      return;\n    }\n\n    if (index > activeTitleIndex) {\n      return;\n    }\n\n    const nextIndex =\n      index === activeTitleIndex\n        ? Math.min(activeTitleIndex, updated.length - 1)\n        : Math.max(activeTitleIndex - 1, 0);\n    handleSelectTitle(nextIndex, updated[nextIndex]);\n  };"""
text, count = block_pattern.subn(new_block, text)
if count != 1:
    raise SystemExit('Failed to replace title handlers block')

map_pattern = re.compile(
    r"                        <AnimatePresence initial=\{false\}>\n                          \{titles.map\((?:.|\n)*?                          \)\}\n                        </AnimatePresence>",
    re.DOTALL,
)
new_map = """                        <AnimatePresence initial={false}>\n                          {titles.map((candidateTitle, i) => {\n                            const isSelected = activeTitleIndex === i;\n                            return (\n                              <motion.div\n                                key={i}\n                                initial={{ opacity: 0, height: 0 }}\n                                animate={{ opacity: 1, height: \"auto\" }}\n                                exit={{ opacity: 0, height: 0 }}\n                                transition={{ duration: 0.2 }}\n                                className={`flex gap-2 items-center mb-1 rounded p-1 ${isSelected ? \"border border-purple-500 bg-[var(--accent)]/20\" : \"\"}`}\n                                onClick={() => handleSelectTitle(i, candidateTitle)}\n                                aria-selected={isSelected}\n                              >\n                                <Tooltip delayDuration={500}>\n                                  <TooltipTrigger asChild>\n                                    <input\n                                      type=\"text\"\n                                      className={`w-full px-2 py-1 rounded bg-[var(--input)] text-xs text-[var(--foreground)] border focus:outline-none focus:ring-1 focus:ring-purple-500 ${isSelected ? \"border-purple-500\" : \"border-[var(--border)]\"}`}\n                                      placeholder={translation?.title_placeholder?.translation ??\n                                        \"New title\"}\n                                      value={candidateTitle}\n                                      onChange={(e) => handleTitleChange(i, e.target.value)}\n                                      onFocus={() => handleSelectTitle(i, candidateTitle)}\n                                    />\n                                  </TooltipTrigger>\n                                  <TooltipContent side=\"top\" className=\"text-xs max-w-xs\">\n                                    {translation?.title_placeholder?.tooltip ??\n                                      \"Enter a video title here for comparison\"}\n                                  </TooltipContent>\n                                </Tooltip>\n\n                                <Tooltip delayDuration={500}>\n                                  <TooltipTrigger asChild>\n                                    <button\n                                      type=\"button\"\n                                      onClick={(event) => {\n                                        event.stopPropagation();\n                                        removeTitle(i);\n                                      }}\n                                      disabled={titles.length <= 1}\n                                      className=\"py-2 text-sm text-muted-foreground hover:text-destructive disabled:opacity-50\"\n                                    >\n                                      <XCircle className=\"w-5 h-5\" />\n                                    </button>\n                                  </TooltipTrigger>\n                                  <TooltipContent side=\"top\" className=\"text-xs max-w-xs\">\n                                    {translation?.title_remove_button?.tooltip ??\n                                      \"Delete this title, it cannot be undone\"}\n                                  </TooltipContent>\n                                </Tooltip>\n                              </motion.div>\n                            );\n                          })}\n                        </AnimatePresence>"""
text, count = map_pattern.subn(new_map, text)
if count != 1:
    raise SystemExit('Failed to replace titles map block')

path.write_text(text.replace('\n', '\r\n'), encoding='utf-8')
